mapper.update:
UPDATE class_session
SET title=#{session.title}, type=#{session.type}, category=#{session.category},
    trainer_id=#{session.trainerId}, trainer_name=#{session.trainerName},
    class_date=#{session.classDate}, start_time=#{session.startTime}, end_time=#{session.endTime},
    capacity=#{session.capacity}
WHERE id=#{session.id} AND gym_id=#{gymId}
